mapper.select:
SELECT order_id, inbound_detail_id, account_id, foreign_product_id, sell_qty, base_price, settlement_fx_rate, status, processed_at
FROM sell_order
WHERE order_id = #{orderId}

SELECT order_id, inbound_detail_id, account_id, foreign_product_id, sell_qty, base_price, settlement_fx_rate, status, processed_at
FROM sell_order
WHERE account_id = #{accountId}

SELECT order_id, inbound_detail_id, account_id, foreign_product_id, sell_qty, base_price, settlement_fx_rate, status, processed_at FROM sell_order WHERE inbound_detail_id IN
#{inboundDetailId}
ORDER BY inbound_detail_id, processed_at ASC
